    // Suspend the resource for transports that require suspension (e.g., long polling, streaming, SSE)
    // WebSocket connections are already persistent and should not be suspended.
    if (!r.isSuspended() && r.getTransport() != AtmosphereResource.TRANSPORT.WEBSOCKET) {
        r.suspend();
    }
    return Action.CONTINUE;
}

