public static int[] toPrimitive(final Integer[] array){
    if (array == null) {
        return null;
    }
    int[] result = new int[array.length];
    for (int i = 0; i < array.length; i++) {
        Integer value = array[i];
        if (value == null) {
            throw new NullPointerException("Array element at index " + i + " is null");
